package presentation.snippets.lesson22.slide110

import presentation.support.*

fun abs(x: Int): Int {
  var result = x
  if (x < 0) result = -x
  return result
}

fun main() {
  check(abs(-3) == 3)
  check(abs(4) == 4)
}
